{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 bucket encryption is not explicitly configured",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The bucket has no Terraform-managed server-side encryption configuration, so encryption requirements are not explicitly enforced by this code."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or deleted backend objects cannot be readily recovered, increasing the risk of permanent state loss."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access is not blocked",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "HIGH",
      "explanation": "The bucket has no public access block configuration, leaving it vulnerable to becoming publicly accessible through a later ACL or bucket policy change."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive bucket deletion is enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to delete the bucket and all of its objects, increasing the impact of an accidental or unauthorized destroy operation."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"changeme_aws_s3_bucket_backend_simple\" {\n  force_destroy = false\n  bucket        = \"changeme-${random_id.changeme_backends_s3_bucket_name.hex}\"\n}\n\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm = \"AES256\"\n    }\n  }\n}\n\nresource \"aws_s3_bucket_versioning\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"changeme_aws_s3_bucket_backend_simple\" {\n  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Disabled destructive bucket deletion, enabled explicit server-side encryption and versioning, and added a complete S3 public access block."
}
